const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"κριθινος", type:"material", gloss:"barley- (made of barley)"},
  {w:"δαφνινος", type:"material", gloss:"laurel-"},
  {w:"φηγινος", type:"material", gloss:"oak-"},
  {w:"πυρινος", type:"material", gloss:"wheat-"},
  {w:"ξυλινος", type:"material", gloss:"wooden"},
  {w:"λιθινος", type:"material", gloss:"stone-"},
  {w:"πετρινος", type:"material", gloss:"rocky/stone-"},
  {w:"γηινος", type:"material", gloss:"earthen"},
  {w:"δερματινος", type:"material", gloss:"leather"},
  {w:"βυσσινος", type:"material", gloss:"byssine/linen"},
  {w:"θερινος", type:"season", gloss:"summer(-time)"},
  {w:"χειμερινος", type:"season", gloss:"winter(-time)"},
  {w:"εαρινος", type:"season", gloss:"spring(-time)"},
  {w:"εσπερινος", type:"season", gloss:"evening"},
  {w:"νυκτερινος", type:"season", gloss:"night"},
  {w:"πρωινος", type:"season", gloss:"morning"},
  {w:"οψινος", type:"season", gloss:"late"},
  {w:"χθεσινος", type:"season", gloss:"yesterday’s"},
  {w:"περυσινος", type:"season", gloss:"last year’s"},
  {w:"αυρινος", type:"season", gloss:"tomorrow’s"},
  {w:"σικινος", type:"material", gloss:"Sikinos (proper name)"},
  {w:"μυρσινος", type:"material", gloss:"Myrsinos (place)"},
  {w:"βιβλινος", type:"material", gloss:"Byblinos (possessive)"},
  {w:"βολβιτινος", type:"material", gloss:"Bolbitinos (possessive)"},
];

// --- Greek-ish normalization helpers ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function normalizeGreekish(input){
  let s = (input||"").trim();
  if(!s) return "";
  // Lowercase; keep Greek; also allow simple Latin transliteration.
  s = s.toLowerCase();
  // Convert common Latin to Greek (very rough, for fun)
  // Do digraphs first.
  const digraphs = [
    [/th/g,'θ'],[/ph/g,'φ'],[/ch/g,'χ'],[/ps/g,'ψ'],[/kh/g,'χ'],[/rh/g,'ῥ'],
    [/ai/g,'αι'],[/ei/g,'ει'],[/oi/g,'οι'],[/ou/g,'ου'],[/au/g,'αυ'],[/eu/g,'ευ'],
  ];
  for(const [re,rep] of digraphs) s = s.replace(re,rep);
  const map = {
    a:'α', b:'β', g:'γ', d:'δ', e:'ε', z:'ζ', h:'η', i:'ι', k:'κ', l:'λ', m:'μ', n:'ν',
    x:'ξ', o:'ο', p:'π', r:'ρ', s:'σ', t:'τ', u:'υ', y:'υ', f:'φ', w:'ω', c:'κ', q:'κ',
    v:'β', j:'ι'
  };
  s = s.replace(/[a-z]/g, ch => map[ch] || ch);
  // Final sigma
  s = s.replace(/σ\b/g,'ς');
  // Strip existing accents/breathings so we can re-accent cleanly
  s = stripDiacritics(s);
  // Normalize iota diaeresis typed as ï etc.
  s = s.replace(/ϊ/g,'ι').replace(/ϋ/g,'υ');
  return s;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);

function syllabifyToy(word){
  // Syllables = contiguous vowel groups with surrounding consonants attached to the right (very rough)
  // We'll just split by vowel-group boundaries and then reattach consonants.
  const chars = [...word];
  let groups = [];
  let cur = "";
  let inV = false;
  for(const ch of chars){
    const isV = vowels.has(ch);
    if(cur === ""){
      cur = ch; inV = isV; continue;
    }
    if(isV === inV){
      cur += ch;
    } else {
      groups.push({text:cur, isVowelGroup:inV});
      cur = ch; inV = isV;
    }
  }
  if(cur) groups.push({text:cur, isVowelGroup:inV});

  // Now build syllables by taking (optional consonant group) + vowel group + (following consonants up to next vowel group, but keep at least one consonant for next syllable if possible)
  // For a toy, we will: each vowel group starts a syllable; preceding consonants attach to it.
  let sylls = [];
  let pendingCons = "";
  for(const g of groups){
    if(!g.isVowelGroup){
      pendingCons += g.text;
    } else {
      sylls.push(pendingCons + g.text);
      pendingCons = "";
    }
  }
  if(pendingCons){
    // trailing consonants attach to last syllable
    if(sylls.length) sylls[sylls.length-1] += pendingCons;
    else sylls.push(pendingCons);
  }
  return sylls.filter(s=>s.length);
}

function endsWithInos(w){
  return w.endsWith('ινος') || w.endsWith('ῖνος') || w.endsWith('ίνος');
}

function guessTypeAuto(w){
  // Toy heuristic: if it matches a known season/adverb list, choose season; else material.
  const bare = stripDiacritics(w);
  const seasonStems = ['θεριν','χειμεριν','εαριν','εσπεριν','νυκτεριν','εωθιν','δειλιν','μετοπωριν','πρωιν','οψιν','χθεσιν','περυσιν','αυριν'];
  for(const st of seasonStems){
    if(bare.startsWith(st)) return 'season';
  }
  return 'material';
}

function addAcuteToVowel(ch){
  // Return precomposed if possible via NFC after combining acute.
  return (ch + '\u0301').normalize('NFC');
}

function accentSyllable(word, syllIndexFromStart){
  const sylls = syllabifyToy(word);
  if(sylls.length === 0) return {accented:word, sylls};
  const idx = Math.max(0, Math.min(sylls.length-1, syllIndexFromStart));
  // Add acute to first vowel in that syllable
  let s = sylls[idx];
  let out = "";
  let done = false;
  for(const ch of [...s]){
    if(!done && vowels.has(ch)){
      out += addAcuteToVowel(ch);
      done = true;
    } else {
      out += ch;
    }
  }
  sylls[idx] = out;
  return {accented: sylls.join(''), sylls};
}

function renderSyllables(sylls, targetIndex, strength){
  if(!sylls.length) return '—';
  return sylls.map((sy, i) => {
    if(i === targetIndex){
      const alpha = 0.10 + (strength/100)*0.25;
      return `<mark style="background: rgba(123,220,255,${alpha.toFixed(3)})">${escapeHtml(sy)}</mark>`;
    }
    return escapeHtml(sy);
  }).join(' · ');
}

function escapeHtml(s){
  return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function apply(){
  const raw = $('#word').value;
  const w = normalizeGreekish(raw);
  $('#norm').textContent = w || '—';

  if(!w){
    $('#accented').textContent = '—';
    $('#syll').textContent = '—';
    $('#explain').textContent = '—';
    return;
  }

  const sylls = syllabifyToy(w);
  const strength = Number($('#dial').value||60);

  if(!endsWithInos(w)){
    $('#accented').textContent = w;
    $('#syll').innerHTML = escapeHtml(sylls.join(' · '));
    $('#explain').innerHTML = `This toy targets words ending in <span class="greek">-ινος</span>. Try adding <span class="greek">ινος</span> at the end.`;
    return;
  }

  let mode = $('#mode').value;
  if(mode === 'auto') mode = guessTypeAuto(w);

  // Determine accent target: proparoxytone = antepenult; oxytone = ultima
  let targetIndex;
  if(mode === 'material'){
    targetIndex = Math.max(0, sylls.length - 3);
  } else {
    targetIndex = sylls.length - 1;
  }

  const {accented, sylls: sylls2} = accentSyllable(w, targetIndex);
  $('#accented').textContent = accented;
  $('#syll').innerHTML = renderSyllables(sylls2, targetIndex, strength);

  const badge = mode === 'material'
    ? '<span class="badge good">proparoxytone</span>'
    : '<span class="badge warn">oxytone</span>';

  const why = mode === 'material'
    ? `Rule-demo: “participation/material” <span class="greek">-ινος</span> → accent the <b>antepenult</b> (Herodian’s list: <span class="greek">ξύλινος, λίθινος</span> …).`
    : `Rule-demo: season/adverbial <span class="greek">-ινος</span> → accent the <b>ultima</b> (e.g. <span class="greek">θερινός, αὐρινός</span>).`;

  $('#explain').innerHTML = `${badge} ${why}`;
}

function randomExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#word').value = ex.w;
  // set mode to match example (but keep auto if user wants)
  if($('#mode').value !== 'auto') $('#mode').value = ex.type;
  apply();
  // Add a little extra info in explanation
  const extra = ` Example meaning: <span class="greek">${escapeHtml(ex.w)}</span> ≈ “${escapeHtml(ex.gloss)}”.`;
  $('#explain').innerHTML += extra;
}

$('#apply').addEventListener('click', apply);
$('#random').addEventListener('click', randomExample);
$('#clear').addEventListener('click', () => { $('#word').value=''; apply(); });
$('#dial').addEventListener('input', apply);
$('#mode').addEventListener('change', apply);
$('#word').addEventListener('keydown', (e)=>{ if(e.key==='Enter') apply(); });

// Seed
$('#apply').classList.add('primary');
$('#word').value = 'ξυλινος';
apply();

